"""Small editable cooked-date caption reuses the existing picker, independent of card settings."""
import copy
from playwright.sync_api import sync_playwright
import promotion_schedule_browser as f
from scheduled_linked_slots_browser import state,compose
f.EXTRA+='''window.actionDateTest={seed:()=>{meals.find(m=>m.id===1).lastCooked='2026-10-22T12:00:00.000Z';persist()},show:value=>{showLastCooked=value;saveLastCookedVisibility();renderList()},menu:(id=1,day=null)=>{const meal=meals.find(m=>m.id===id);openTopMealActionMenu(day,meal.cat,meal)},record:id=>meals.find(m=>m.id===id),chooser:()=>promotionTest.chooser('Saturday','Weekend')};'''
def menu(p):return p.get_by_role('dialog',name='Meal options',exact=True)
def caption(p):return menu(p).locator('.meal-options-last-cooked')
def picker(p):return p.get_by_role('heading',name='Edit last cooked date',exact=True).locator('..')
def run(b,name,w,show):
 c,p,e,pr=f.setup(b,name,w,'multiple');p.evaluate('actionDateTest.seed()');p.evaluate('v=>actionDateTest.show(v)',show);p.evaluate('promotionTest.groups()');assert bool(p.locator('#list .meal-last-cooked').count())==show;before=copy.deepcopy(state(p));schedule=compose(p);p.evaluate('actionDateTest.menu()');d=menu(p);assert caption(p).inner_text()=='Last cooked: Oct 22, 2026';assert not d.get_by_role('button',name='Edit last cooked date',exact=True).count();assert [s for s in d.locator(':scope>div:last-child>button').all_text_contents()]==['Open recipe','Edit meal','Edit grocery list']
 title=d.get_by_text('Pernil',exact=True).bounding_box();date=caption(p).bounding_box();assert date['y']>=title['y']+title['height'];assert caption(p).locator('svg').count()==1 and caption(p).evaluate('(el)=>getComputedStyle(el).fontSize')=='12px';caption(p).tap();d2=picker(p);assert d2.get_by_label('Choose last cooked date',exact=True).input_value()=='2026-10-22';d2.get_by_label('Choose last cooked date',exact=True).fill('2026-11-01');d2.get_by_role('button',name='Save',exact=True).tap();assert d.is_visible() and caption(p).inner_text()=='Last cooked: Nov 1, 2026';assert p.evaluate('actionDateTest.record(1).lastCooked').startswith('2026-11-01') and compose(p)==schedule
 caption(p).locator('svg').tap();d2=picker(p);d2.get_by_role('button',name='Clear date',exact=True).tap();p.get_by_role('button',name='No',exact=True).tap();assert d2.is_visible() and caption(p).inner_text()=='Last cooked: Nov 1, 2026';d2.get_by_role('button',name='Clear date',exact=True).tap();p.get_by_role('button',name='Yes',exact=True).tap();assert d.is_visible() and caption(p).inner_text()=='Last cooked: Never';assert not p.evaluate('actionDateTest.record(1).lastCooked') and compose(p)==schedule
 caption(p).tap();assert picker(p).get_by_label('Choose last cooked date',exact=True).input_value()=='';picker(p).get_by_label('Choose last cooked date',exact=True).fill('2026-10-30');picker(p).get_by_role('button',name='Cancel',exact=True).tap();assert caption(p).inner_text()=='Last cooked: Never';d.get_by_role('button',name='Close meal options',exact=True).tap();p.evaluate('actionDateTest.menu()');assert caption(p).inner_text()=='Last cooked: Never';caption(p).tap();picker(p).get_by_label('Choose last cooked date',exact=True).fill('2026-10-29');picker(p).get_by_role('button',name='Save',exact=True).tap();d.get_by_role('button',name='Close meal options',exact=True).tap();p.reload();p.evaluate('actionDateTest.menu()');assert caption(p).inner_text()=='Last cooked: Oct 29, 2026';p.screenshot(path='/tmp/meal-action-cooked-date-'+name+'-'+str(w)+'-'+str(show)+'.png');d.get_by_role('button',name='Close meal options',exact=True).tap();p.evaluate('actionDateTest.chooser()');assert p.locator('.weekday-choice-cooked').filter(has_text='Last cooked Oct 29, 2026').count() and not p.locator('.weekday-choice-cooked').filter(has_text='Last cooked:').count();p.locator('.weekday-meal-picker').get_by_role('button',name='Cancel',exact=True).tap()
 p.evaluate('actionDateTest.menu(2)');assert caption(p).inner_text()=='Last cooked: Never';d.get_by_role('button',name='Close meal options',exact=True).tap();p.evaluate('actionDateTest.menu(1,"Saturday")');scheduled=p.get_by_role('dialog',name='Meal options for Saturday',exact=True);assert scheduled.locator('.meal-options-last-cooked').inner_text()=='Last cooked: Oct 29, 2026';assert scheduled.locator(':scope>div:last-child>button').all_text_contents()==['Open recipe','Change meal','Skip This Week','Edit meal','Edit grocery list'];p.set_viewport_size({'width':740,'height':360});assert scheduled.bounding_box()['height']<=324;scheduled.get_by_role('button',name='Edit grocery list',exact=True).scroll_into_view_if_needed();scheduled.get_by_role('button',name='Close meal options',exact=True).tap()
 for old in before['meals']:
  new=p.evaluate('id=>actionDateTest.record(id)',old['id']);assert {k:v for k,v in old.items() if k!='lastCooked'}=={k:v for k,v in new.items() if k!='lastCooked'}
 assert not e,e
 if pr:assert p.evaluate("localStorage.getItem('mealRotationDataV1')")=='WORKING SENTINEL'
 print('PASS',name,w,'card date setting',show,'caption below title with pencil, saved/Never, existing picker prefill/save/clear/cancel, live caption, unchanged action order, reopening/reload and recipe/schedule preservation',flush=True);c.close()
if __name__=='__main__':
 with sync_playwright() as pw:
  b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
  for name in ['index.html','meal-rotation-test.html']:
   for w in [320,360]:
    for show in [False,True]:run(b,name,w,show)
  b.close()
